.c-anime .image-cutter, /*search/character page & character tooltip*/
.entry-tooltip_container > .image-link, /*anime tooltip*/
.b-db_entry-variant-list_item[data-id][data-type="anime"] .image, /*search results*/
[content]+.b-db_entry .c-poster, /*anime page poster*/
[href]+.b-db_entry .c-poster, 
.b-menu_logo > a /*topic right poster*/ {
    position: relative;
/*    display: inline-block;*/
    &::after {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
		background-size: cover !important;
/*        background-size: contain !important;*/ /* requires white background which makes original poster hidden */
		background-repeat: no-repeat !important;
        background-position: center !important;
/*		background-color: white;*/
/*        z-index: 1;*/
        pointer-events: none;
    }
/*    & img {
        display: block;
        max-width: 100%;
    }*/
    &:hover::after {
        opacity: 0;
    }
}
